def vigenere_decrypt(ciphertext, key):
    result = []
    key = key.upper()
    for i, c in enumerate(ciphertext):
        if c.isalpha():
            k = key[i % len(key)]
            p = (ord(c.upper()) - ord('A') - (ord(k) - ord('A'))) % 26
            result.append(chr(p + ord('A')))
        else:
            result.append(c)
    return ''.join(result)

